            float2 st = amzLayerNorm();
            st -= 0.5;
            if( layer.x < layer.y ) {
                st.x *= layer.x/layer.y;
            } else {
                st.y *= layer.y/layer.x;
            }
            st /= amzp_scale;
            st /= 6.0;
            float3 ro = float3(0., 1., -1.);
            float3 rd = normalize(float3(st, 1.));
            float2 dinf = march(ro,rd);
            float d = dinf.x;
            float dz = dinf.y;
            float3 p = ro + rd * d;
            float3 n = calcNormal(p,rd);
            float3 nn = n;
            float4 localCoord = float4(p-(amzp_position/100.), 1.);
            n = (float4(n,0.) * rotateAndOrient).xyz;
            localCoord *= rotateAndOrient;
            float4 pp = localCoord;
            float4 qq = pp * (vecToVec(n,pp.xyz*float3(0.,1.,0.)));
            pp /= float4((amzp_stretch.x*0.5*layer.x/max(layer.x,layer.y) ),(amzp_stretch.y*0.5*layer.y/max(layer.x,layer.y) ),amzp_depth,1.);
