            if( blurColor.a > baseColor.a && blurColor.a > 0.25 ) {
                texColor = blurColor / blurColor.a;
            } else if( baseColor.a > 0.25 ) {
                texColor = baseColor / baseColor.a;
            } else {
                texColor = baseColor;
            }
                if((amzp_inton>0.5)) {
