                if( amzp_interiorBlend > 0.0 ) {
                    texColor = mix(texColor,amzp_interiorColor*texColor.a,amzp_interiorBlend);
                }
                if( amzp_fadeBlend > 0.0 ) {
                    texColor = mix(texColor,amzp_fadeColor*texColor.a,amzp_fadeBlend*dz);
                }
            }
         }
            amzOutput = applyShading(texColor, p, nn, d) * a;
        }

